def write_introduction(w):
 w.structural('ВВЕДЕНИЕ')
 paras(w,
 'Обслуживание физических лиц в отделениях банка объединяет учёт клиентов, счетов, карт, переводов и кредитных договоров. Проверка основания, изменение данных и выдача документа должны давать согласованный результат: ошибка связанной записи способна исказить остаток, повторить перевод или нарушить график платежей.',
 'Раздельное ведение сведений требует повторного ввода и сверки. Руководителю операционного направления нужно обеспечить правильное и своевременное обслуживание при ограниченном кадровом ресурсе. Автоматизация повторяемой работы рассматривается как способ уменьшить ручной труд с сохранением контроля.',
 'Цель работы — спроектировать информационную систему согласованного оформления счетов, карт, внутрибанковских переводов и утверждённых кредитных договоров. Объект — обслуживание физических лиц в отделениях банка; предмет — данные, функции и программные средства учёта, документирования и контроля операций.',
 'Назначение и критерии результата определяют требования, модели данных, функций и процессов. Архитектура и технический проект задают ответственность компонентов и правила обработки. Методики испытаний предусматривают проверку операций и сравнение полного труда на обслуживание.')


def paras(w,*texts):
 for text in texts:w.p(text)

def sub(w,title,*texts):w.h(title);paras(w,*texts)

