 paras(w,'Денежные проверки углублены до сбоя, повтора, конкуренции и защиты истории. План сверяется с независимым эталоном; документы — с исходными фактами. Восстановление и перенос проверяются до сравнения полного труда и решения заказчика.')
 sub(w,'7.4 Условия и порядок проведения',
 'Порядок: комплектность и запуск, реквизиты, денежные и кредитные операции, отчёты и права, восстановление и перенос, нагрузка, обращения, труд и решение. Независимый случай начинается с известной фикстуры.',
 'И09 прерывает обработку между списанием и зачислением с проверкой account/transfer/audit_event. И11 запускает два соединения через барьер с обоими победителями и чтением после ожидания. И15 проверяет откат договора и плана при отказе второй строки.',
 'До И24 завершаются предметные проверки, утверждаются ручной регламент А, одинаковые данные, состав сотрудников и результаты. Тридцать пар содержат допустимые задания с одинаковыми документами и проверками; отрицательные случаи выполняются отдельно.',
 'После тренировки порядок пар чередуется А→Б/Б→А. Наблюдатель сохраняет интервалы труда всех участников, помощь, повторы, исправления и сверку. Труд сотрудников суммируется без двойного учёта времени одного человека; измерительная работа исключается одинаково для А и Б.',
 'Верное обращение Q подтверждается документом и состоянием относительно эталона. Полный журнал, сопоставимые условия и Q_A=Q_B=30 допускают сравнение u=L/Q с ЦП1–ЦП4. Неполная база не подтверждает эффект.')
 table(w,'Журнал сравнительного испытания',['Поле','Содержание'],[
 ('Идентификация','pair_id; вид обращения; способ А/Б; порядок; версия регламента и набора'),('Труд','Исполнитель, роль, квалификация, интервалы; помощь, повторы и исправления'),('Результат','Документ; ID записей; правильность; критические нарушения'),('Свидетельства','Снимок состояния, журналы, таймер, способ сверки и SHA-256'),('Сводка','L_A, L_B, Q_A, Q_B, u_A, u_B, относительное сокращение и решение')],[38,127])
